import { useEffect, useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import axios from "axios";

export default function Editar() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [usuario, setUsuario] = useState({});
  const [foto, setFoto] = useState(null);

  useEffect(() => {
    axios.get(`http://localhost:3001/usuarios/${id}`)
      .then(res => setUsuario(res.data))
      .catch(err => console.error("Erro ao carregar perfil:", err));
  }, [id]);

  const handleChange = (e) => {
    setUsuario({ ...usuario, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    for (const chave in usuario) {
      formData.append(chave, usuario[chave]);
    }
    if (foto) formData.append("foto", foto);

    try {
      await axios.put(`http://localhost:3001/usuarios/${id}`, formData, {
        headers: {
          "Content-Type": "multipart/form-data"
        }
      });
      alert("Usuário atualizado!");
      navigate(`/perfil/${id}`);
    } catch (error) {
      console.error("Erro ao atualizar:", error);
      alert("Erro ao atualizar.");
    }
  };

  return (
    <div>
      <h3>Editar Usuário</h3>
      <form onSubmit={handleSubmit} encType="multipart/form-data">
        <input name="nome" value={usuario.nome || ""} onChange={handleChange} placeholder="Nome" className="form-control mb-2" />
        <input name="idade" value={usuario.idade || ""} onChange={handleChange} placeholder="Idade" className="form-control mb-2" />
        <input name="rua" value={usuario.rua || ""} onChange={handleChange} placeholder="Rua" className="form-control mb-2" />
        <input name="bairro" value={usuario.bairro || ""} onChange={handleChange} placeholder="Bairro" className="form-control mb-2" />
        <input name="estado" value={usuario.estado || ""} onChange={handleChange} placeholder="Estado" className="form-control mb-2" />
        <textarea name="biografia" value={usuario.biografia || ""} onChange={handleChange} placeholder="Biografia" className="form-control mb-2" />
        <input type="file" onChange={(e) => setFoto(e.target.files[0])} className="form-control mb-2" />
        <button className="btn btn-primary">Salvar Alterações</button>
      </form>
    </div>
  );
}
